$ccp_get_color = function($key, $fallback) {
    $value = (string)$this->config->get($key);
    return preg_match('/^#[0-9a-fA-F]{6}$/', $value) ? $value : $fallback;
};

$ccp_container_width = (int)$this->config->get('theme_codecart_pro_container_width');
if ($ccp_container_width < 1400 || in_array($ccp_container_width, array(1560, 1640), true)) { $ccp_container_width = 1500; }
$ccp_card_radius = (int)$this->config->get('theme_codecart_pro_card_radius');
$ccp_element_radius = (int)$this->config->get('theme_codecart_pro_element_radius');
$ccp_button_radius = (int)$this->config->get('theme_codecart_pro_button_radius');
