$ccp_theme_directory_key = $ccp_config_theme ? 'theme_' . $ccp_config_theme . '_directory' : '';
$ccp_theme_directory = $ccp_theme_directory_key ? (string)$this->config->get($ccp_theme_directory_key) : '';
$ccp_is_codecart_theme = ($ccp_config_theme === 'codecart_pro' || $ccp_theme_directory === 'codecart_pro' || (string)$this->config->get('config_template') === 'codecart_pro');
if ($ccp_is_codecart_theme && (int)$this->config->get('theme_codecart_pro_status')) {
// CodeCart PRO v8.7.7: logo must also go through image/cache so AVIF/WebP/JXL processing can replace it reliably.
