) {
    $ccp_page_side_background_image = rtrim((!empty($this->request->server['HTTPS']) ? HTTPS_SERVER : HTTP_SERVER), '/') . '/image/' . ltrim($ccp_page_side_background_image, '/');
} else {
    $ccp_page_side_background_image = '';
}
