// Ignore obsolete manual information-mode snippets immediately, even before
// the administrator opens the settings page and the migration clears them.
foreach (array('ccp_custom_css_global','ccp_custom_css_header','ccp_custom_css_menu','ccp_custom_css_product_card','ccp_custom_css_category','ccp_custom_css_product','ccp_custom_css_mobile','ccp_custom_css_checkout','ccp_custom_css') as $ccp_custom_css_key) {
    $ccp_custom_css_value = isset($data[$ccp_custom_css_key]) ? (string)$data[$ccp_custom_css_key] : '';
    $ccp_custom_css_legacy = strpos($ccp_custom_css_value, 'ccp-information-mode-manual') !== false
        || strpos($ccp_custom_css_value, 'CodeCart PRO: информационный режим без продаж') !== false
        || (strpos($ccp_custom_css_value, '.ccp-header-cart-link') !== false && strpos($ccp_custom_css_value, '.ccp-product-card__price') !== false && strpos($ccp_custom_css_value, 'display: none !important') !== false);
    if ($ccp_custom_css_legacy) { $data[$ccp_custom_css_key] = ''; }
}
foreach (array('ccp_custom_js_head') as $ccp_custom_js_key) {
    $ccp_custom_js_value = isset($data[$ccp_custom_js_key]) ? (string)$data[$ccp_custom_js_key] : '';
    $ccp_custom_js_legacy = strpos($ccp_custom_js_value, 'ccp-information-mode-manual') !== false
        || strpos($ccp_custom_js_value, 'salesSelector') !== false
        || strpos($ccp_custom_js_value, 'hiddenSelectors') !== false
        || strpos($ccp_custom_js_value, 'removeSalesElements') !== false
        || (strpos($ccp_custom_js_value, 'CodeCartProTheme.quantitySwitch') !== false && strpos($ccp_custom_js_value, 'MutationObserver') !== false);
    if ($ccp_custom_js_legacy) { $data[$ccp_custom_js_key] = ''; }
}
