$ccp_social_url = function($value, $service) {
    $value = trim((string)$value);
    if ($value === '') { return ''; }
    if (preg_match('#^https?://#i', $value)) {
        return filter_var($value, FILTER_VALIDATE_URL) ? $value : '';
    }
    if ($service === 'telegram') {
        if (stripos($value, 'tg://') === 0) { return $value; }
        if (preg_match('#^(?:t\\.me|telegram\\.me)/([A-Za-z][A-Za-z0-9_]{4,31})/?$#i', $value, $m)) { return 'https://t.me/' . $m[1]; }
        $username = ltrim($value, '@');
        return preg_match('/^[A-Za-z][A-Za-z0-9_]{4,31}$/', $username) ? 'https://t.me/' . $username : '';
    }
    if ($service === 'viber') {
        if (stripos($value, 'viber://') === 0) { return $value; }
        $digits = preg_replace('/\\D+/', '', $value);
        return strlen($digits) >= 7 ? 'viber://chat?number=%2B' . $digits : '';
    }
    if ($service === 'whatsapp') {
        if (stripos($value, 'whatsapp://') === 0) { return $value; }
        $digits = preg_replace('/\\D+/', '', $value);
        return strlen($digits) >= 7 ? 'https://wa.me/' . $digits : '';
    }
    return '';
};
$data['ccp_floating_telegram'] = $ccp_social_url($this->config->get('theme_codecart_pro_floating_telegram'), 'telegram');
