$data['help_ccp_changelog'] = $ccp_admin_is_ru ? 'Укажите изменения по версиям для этого модуля. Вкладка на витрине появится только если поле заполнено.' : ($ccp_admin_is_uk ? 'Вкажіть зміни за версіями для цього модуля. Вкладка на вітрині з’явиться лише якщо поле заповнене.' : 'Add version changes for this module. The storefront tab is shown only when this field is filled.');
$data['ccp_product_changelog'] = array();
$ccp_product_id = isset($this->request->get['product_id']) ? (int)$this->request->get['product_id'] : 0;
if (isset($this->request->post['ccp_product_changelog']) && is_array($this->request->post['ccp_product_changelog'])) {
    $data['ccp_product_changelog'] = $this->request->post['ccp_product_changelog'];
} elseif ($ccp_product_id) {
    $this->load->model('extension/theme/codecart_pro_product');
    $data['ccp_product_changelog'] = $this->model_extension_theme_codecart_pro_product->getChangelog($ccp_product_id);
}
}

// CodeCart PRO Theme v8.7.7: product changelog editor data.
if ((int)$this->config->get('theme_codecart_pro_status') && !isset($data['tab_ccp_changelog'])) {
    $ccp_admin_language_code = (string)$this->config->get('config_language');
    $ccp_admin_is_ru = (strpos($ccp_admin_language_code, 'ru') === 0);
    $ccp_admin_is_uk = (strpos($ccp_admin_language_code, 'uk') === 0 || strpos($ccp_admin_language_code, 'ua') === 0);
    $data['tab_ccp_changelog'] = $ccp_admin_is_ru ? 'История изменений' : ($ccp_admin_is_uk ? 'Історія змін' : 'Changelog');
    $data['entry_ccp_changelog'] = $data['tab_ccp_changelog'];
    $data['help_ccp_changelog'] = $ccp_admin_is_ru ? 'Укажите изменения по версиям для этого модуля. Вкладка на витрине появится только если поле заполнено.' : ($ccp_admin_is_uk ? 'Вкажіть зміни за версіями для цього модуля. Вкладка на вітрині з’явиться лише якщо поле заповнене.' : 'Add version changes for this module. The storefront tab is shown only when this field is filled.');
    $data['ccp_product_changelog'] = array();
    $ccp_product_id = isset($this->request->get['product_id']) ? (int)$this->request->get['product_id'] : 0;
    if (isset($this->request->post['ccp_product_changelog']) && is_array($this->request->post['ccp_product_changelog'])) {
        $data['ccp_product_changelog'] = $this->request->post['ccp_product_changelog'];
    } elseif ($ccp_product_id) {
    $this->load->model('extension/theme/codecart_pro_product');
    $data['ccp_product_changelog'] = $this->model_extension_theme_codecart_pro_product->getChangelog($ccp_product_id);
    }
}

{% if tab_ccp_changelog is defined and tab_ccp_changelog %}
<li><a href="#tab-ccp-changelog" data-toggle="tab">{{ tab_ccp_changelog }}</a></li>
{% endif %}

if (!empty($json['success']) && isset($product_info, $option) && (int)$this->config->get('theme_codecart_pro_status') && (string)$this->config->get('config_theme') === 'codecart_pro' && ($this->customer->isLogged() || !$this->config->get('config_customer_price'))) {
    foreach ($this->cart->getProducts() as $ccp_cart_product) {
        if ((int)$ccp_cart_product['product_id'] !== (int)$this->request->post['product_id']) { continue; }
        $ccp_selected_options = array();
        foreach ($ccp_cart_product['option'] as $ccp_cart_option) {
            $ccp_option_id = (int)$ccp_cart_option['product_option_id'];
            if ($ccp_cart_option['type'] === 'checkbox') {
                $ccp_selected_options[$ccp_option_id][] = (string)$ccp_cart_option['product_option_value_id'];
            } else {
                $ccp_selected_options[$ccp_option_id] = in_array($ccp_cart_option['type'], array('select', 'radio', 'image'), true) ? (string)$ccp_cart_option['product_option_value_id'] : (string)$ccp_cart_option['value'];
            }
        }
        $ccp_requested_options = $option;
        foreach ($ccp_requested_options as &$ccp_option_value) {
            if (is_array($ccp_option_value)) { $ccp_option_value = array_map('strval', $ccp_option_value); sort($ccp_option_value); }
            else { $ccp_option_value = (string)$ccp_option_value; }
        }
        unset($ccp_option_value);
        foreach ($ccp_selected_options as &$ccp_option_value) { if (is_array($ccp_option_value)) { sort($ccp_option_value); } }
        unset($ccp_option_value);
        ksort($ccp_requested_options); ksort($ccp_selected_options);
        if ($ccp_requested_options != $ccp_selected_options) { continue; }
        $ccp_added_quantity = max(1, (int)$quantity);
        $ccp_unit_price = $this->tax->calculate($ccp_cart_product['price'], $ccp_cart_product['tax_class_id'], $this->config->get('config_tax'));
        $json['ccp_cart_item'] = array('quantity' => $ccp_added_quantity, 'price' => $this->currency->format($ccp_unit_price, $this->session->data['currency']), 'total' => $this->currency->format($ccp_unit_price * $ccp_added_quantity, $this->session->data['currency']));
        break;
    }
}
